using V=arkjson::Value;namespace fs=std::filesystem;
static int checks=0;
static void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
template<class F>static void fails(F action,const char* why){bool caught=false;try{action();}catch(const std::runtime_error&){caught=true;}check(caught,why);}
static V json(const std::string& text){V value;if(!arkjson::parse(text,value))throw std::runtime_error("test JSON");return value;}
static std::string utf8(const fs::path& path){auto text=path.u8string();return std::string(text.begin(),text.end());}
static void write(const fs::path& path,const std::string& text){std::ofstream output(path,std::ios::binary);output<<text;if(!output)throw std::runtime_error("write test fixture");}
struct Workspace {fs::path path;Workspace(){path=fs::temp_directory_path()/("ark-component-test-"+std::to_string(std::chrono::high_resolution_clock::now().time_since_epoch().count()));fs::create_directories(path);}~Workspace(){std::error_code error;fs::remove_all(path,error);}};
static ark::ComponentLibraryConfig config(const fs::path& root){ark::ComponentLibraryConfig cfg;cfg.rootDirectory=utf8(root);return cfg;}
static std::string step(const std::string& label="component"){return "ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION(('"+label+"'),'2;1');\nENDSEC;\nDATA;\n#1=CARTESIAN_POINT('',(0.,0.,0.));\nENDSEC;\nEND-ISO-10303-21;\n";}
static V fakeNative(const std::string& path,const std::string& hash,int body){V result=json(R"({"native_data":{"brep_base64":"offline-test-fixture-not-production","report":{"brep_valid":true,"kernel":"offline-test"}},"source_solid_count":1})");result.set("source_sha256",V::makeStr(hash));result.set("body_index",V::makeNum(body<0&&body!=-2?0:body));result.set("inspected_path",V::makeStr(path));return result;}
static V screw(){return json(R"({"name":"Socket screw M6 x 20","category":"parafuso","standard":"ISO 4762","thread_diameter_mm":6,"thread_pitch_mm":1,"length_mm":20,"material":"Steel","manufacturer":"Declared supplier","part_number":"SC-M6-20","strength_class":"8.8","head_type":"socket","drive_type":"hex","provenance":"offline metadata test","source_url":"https://example.invalid/catalogue","license":"caller asserts reuse permitted","aliases":["parafuso sextavado","socket screw"]})");}
static void ingestionAndSearch(){
    Workspace workspace;auto root=workspace.path/"library";auto source=workspace.path/"ISO-9999-M99.step";write(source,step());ark::ComponentLibrary library(config(root));int validations=0;auto validator=[&](auto& path,auto& hash,int body){++validations;check(fs::exists(fs::u8path(path))&&fs::u8path(path)!=source,"validator receives copied library snapshot");return fakeNative(path,hash,body);};
    auto imported=library.ingest(utf8(source),screw(),validator);auto id=imported.find("id")->str;check(!imported.find("deduplicated")->b&&imported.find("revision")->num==1&&id.find("sha256:")==0&&id.find(":body:0")!=std::string::npos,"stable hash/body identity and revision");
    check(imported.find("metadata_authority")->str=="declared"&&!imported.find("manufacturing_qualified")->b&&imported.find("metadata")->find("standard")->str=="ISO 4762","caller standard preserved without filename inference");
    auto again=library.ingest(utf8(source),screw(),validator);check(again.find("id")->str==id&&again.find("deduplicated")->b&&library.info().find("components")->num==1,"hash/body ingest idempotently deduplicates");
    auto search=library.search(json(R"({"text":"parafuso","category":"screw","standard":"iso-4762","thread_diameter_mm":6,"thread_pitch_mm":1,"length_mm":20,"strength_class":"8.8","drive_type":"HEX"})"));check(search.find("components")->arr.size()==1,"FTS Portuguese alias plus normalized exact dimensions and attributes");
    check(library.search(json(R"({"thread_diameter_mm":6.00001})")).find("components")->arr.empty(),"exact dimension lookup does not silently widen tolerance");check(library.search(json(R"({"pin_count":6})")).find("components")->arr.empty(),"missing attribute never matches numeric filter");
    auto data=library.get(id,true);check(data.find("native_data")->find("report")->find("brep_valid")->b&&fs::exists(fs::u8path(data.find("step_path")->str)),"verified immutable native data and source path retrievable");
    fs::remove(source);check(fs::exists(fs::u8path(library.resolveStep(id))),"original source deletion preserves library authority");auto conflict=screw();conflict.set("material",V::makeStr("Aluminium"));write(source,step());fails([&]{library.ingest(utf8(source),conflict,validator);},"duplicate content conflicting metadata does not overwrite");
    auto updated=library.update(id,1,conflict);check(updated.find("revision")->num==2&&library.search(json(R"({"material":"aluminium"})")).find("components")->arr.size()==1,"explicit metadata update advances revision and search indexes");fails([&]{library.update(id,1,screw());},"stale metadata revision rejected");
    auto washer=screw();washer.set("name",V::makeStr("Declared washer"));washer.set("category",V::makeStr("washer"));washer.set("inner_diameter_mm",V::makeNum(6.4));washer.set("outer_diameter_mm",V::makeNum(12));washer.set("thickness_mm",V::makeNum(1.6));write(source,step("washer"));library.ingest(utf8(source),washer,validator);check(library.search(json(R"({"category":"anilha","inner_diameter_mm":6.4,"outer_diameter_mm":12,"thickness_mm":1.6})")).find("components")->arr.size()==1,"washer facets and Portuguese category indexed");
    auto connector=json(R"({"name":"Declared electrical connector","category":"connector","pin_count":6,"pin_pitch_mm":2.54,"rated_voltage_v":250,"rated_current_a":5,"aliases":["conector elétrico"]})");write(source,step("connector"));library.ingest(utf8(source),connector,validator,-2);check(library.search(json(R"({"text":"conector","pin_count":6,"pin_pitch_mm":2.54,"rated_current_a":5})")).find("components")->arr.size()==1,"electrical facets indexed and source compound supported");
    check(validations>=5,"offline validator was actually called");fails([&]{library.search(json(R"({"sql":"DROP TABLE components"})"));},"arbitrary query language unavailable");fails([&]{library.search(json(R"({"pin_count":6.5})"));},"fractional pin_count filter rejected");fails([&]{library.search(json(R"({"limit":101})"));},"search result bound enforced");
    auto invalid=screw();invalid.set("metadata_verified",V::makeBool(true));fails([&]{library.ingest(utf8(source),invalid,validator);},"model-authored metadata verification flag rejected");invalid=screw();invalid.set("review_state",V::makeStr("reviewed"));fails([&]{library.update(id,2,invalid);},"review state requires reviewer evidence");
    write(source,"not a STEP file");fails([&]{library.ingest(utf8(source),screw(),validator);},"invalid STEP header rejected before validation");write(source,step("bad-evidence"));fails([&]{library.ingest(utf8(source),screw(),[](auto& path,auto&,int body){return fakeNative(path,std::string(64,'0'),body);});},"native source digest mismatch rejected");fails([&]{library.ingest(utf8(source),screw(),[](auto& path,auto& hash,int body){write(fs::u8path(path),step("mutated snapshot"));return fakeNative(path,hash,body);});},"snapshot mutation during native inspection rejected");
    auto package=library.get(id,true);auto nativePath=root/fs::u8path(package.find("native_relpath")->str);write(nativePath,"tampered");fails([&]{library.get(id,true);},"native package tampering detected on reuse");auto stepPath=fs::u8path(library.resolveStep(id));write(stepPath,step("tampered"));fails([&]{library.resolveStep(id);},"STEP blob tampering detected on reuse");
}
static void multiAgentTransactions(){
    Workspace workspace;auto source=workspace.path/"shared.step";write(source,step("shared"));auto settings=config(workspace.path/"library");ark::ComponentLibrary initial(settings);std::vector<std::unique_ptr<ark::ComponentLibrary>> libraries;for(int i=0;i<4;++i)libraries.push_back(std::make_unique<ark::ComponentLibrary>(settings));std::atomic_int failures=0;std::vector<std::string> ids(4);std::vector<std::thread> agents;
    for(int i=0;i<4;++i)agents.emplace_back([&,i]{try{ids[i]=libraries[i]->ingest(utf8(source),screw(),fakeNative).find("id")->str;}catch(...){++failures;}});for(auto& agent:agents)agent.join();check(failures==0&&std::all_of(ids.begin(),ids.end(),[&](const auto& id){return id==ids[0];})&&initial.info().find("components")->num==1,"concurrent independent agent transactions deduplicate one source/body");
    auto second=initial.ingest(utf8(source),screw(),fakeNative,1);auto compound=initial.ingest(utf8(source),screw(),fakeNative,-2);check(second.find("id")->str!=ids[0]&&compound.find("id")->str!=ids[0]&&initial.info().find("source_files")->num==1&&initial.info().find("components")->num==3,"selected bodies and explicit full compound retain distinct artifacts with one source blob");
    std::atomic_int successes=0,conflicts=0;agents.clear();for(int i=0;i<4;++i)agents.emplace_back([&,i]{auto update=screw();update.set("description",V::makeStr("Agent proposal "+std::to_string(i)));try{libraries[i]->update(ids[0],1,update);++successes;}catch(const std::runtime_error&){++conflicts;}});for(auto& agent:agents)agent.join();check(successes==1&&conflicts==3&&initial.get(ids[0]).find("revision")->num==2,"concurrent metadata proposals commit one revision and reject three stale updates");
}
static void downloadEvidenceContracts(){
    Workspace workspace;const auto source=workspace.path/"public.step";const auto bytes=step("public-download-fixture");write(source,bytes);ark::ComponentLibrary library(config(workspace.path/"library"));
    auto downloaded=ark::fetchComponentResource("https://supplier.example/model.step",ark::ComponentResourceKind::Step,{},[&](const std::string&,std::size_t){return ark::ComponentHttpResponse{200,bytes,"application/step",""};});auto declarations=screw();declarations.set("download_evidence",downloaded.receipt);auto stored=library.ingest(utf8(source),declarations,fakeNative);const auto id=stored.find("id")->str;check(stored.find("metadata")->find("download_evidence")->find("sha256")->str==stored.find("source_sha256")->str&&stored.find("metadata_authority")->str=="declared"&&!stored.find("manufacturing_qualified")->b,"stored network receipt binds bytes and remains declared historical metadata");
    auto newer=downloaded.receipt;newer.set("retrieved_at_utc",V::makeStr("2030-01-01T00:00:00Z"));declarations.set("download_evidence",newer);auto again=library.ingest(utf8(source),declarations,fakeNative);check(again.find("deduplicated")->b&&again.find("metadata")->find("download_evidence")->find("retrieved_at_utc")->str==downloaded.receipt.find("retrieved_at_utc")->str,"refetch deduplicates unchanged declarations and retains first stored receipt");
    auto invalid=newer;invalid.set("sha256",V::makeStr(std::string(64,'0')));declarations.set("download_evidence",invalid);fails([&]{library.ingest(utf8(source),declarations,fakeNative);},"receipt hash cannot describe other source bytes");fails([&]{library.update(id,1,declarations);},"metadata update cannot replace immutable source digest");
    invalid=newer;invalid.set("byte_size",V::makeNum(bytes.size()+1));declarations.set("download_evidence",invalid);fails([&]{library.ingest(utf8(source),declarations,fakeNative);},"receipt byte count binds complete source bytes");
    invalid=newer;invalid.set("headers",json(R"({"Authorization":"fixture-must-not-persist"})"));declarations.set("download_evidence",invalid);fails([&]{library.update(id,1,declarations);},"arbitrary authentication headers cannot be saved as evidence");
    invalid=newer;invalid.set("source_policy",json(R"({"vendor":"kicad","password":"fixture-must-not-persist"})"));declarations.set("download_evidence",invalid);fails([&]{library.update(id,1,declarations);},"nested credential fields cannot be saved as policy evidence");
    invalid=newer;invalid.set("requested_url",V::makeStr("https://supplier.example/model.step?api_key=fixture-must-not-persist"));declarations.set("download_evidence",invalid);fails([&]{library.update(id,1,declarations);},"credential URLs cannot enter persisted download receipts");
    invalid=newer;invalid.set("credentials_sent",V::makeBool(true));declarations.set("download_evidence",invalid);fails([&]{library.update(id,1,declarations);},"public receipts cannot assert authenticated transmission");check(library.get(id).find("revision")->num==1,"rejected evidence updates leave library revision unchanged");
}
static void sql(sqlite3* db,const char* statement){char* error=nullptr;auto rc=sqlite3_exec(db,statement,nullptr,nullptr,&error);std::string detail=error?error:"";sqlite3_free(error);if(rc!=SQLITE_OK)throw std::runtime_error("benchmark database: "+detail);}
static double percentile(std::vector<double> values,double p){std::sort(values.begin(),values.end());return values[(std::size_t)((values.size()-1)*p)];}
static void catalogBenchmark(const std::string& outputPath){
    Workspace workspace;auto root=workspace.path/"catalogue";ark::ComponentLibrary library(config(root));sqlite3* db=nullptr;check(sqlite3_open(utf8(root/"components.sqlite3").c_str(),&db)==SQLITE_OK,"open benchmark metadata fixture");struct Close {sqlite3* db;~Close(){sqlite3_close(db);}} close{db};sql(db,"PRAGMA journal_mode=WAL;BEGIN IMMEDIATE");sqlite3_stmt* insert=nullptr;const char* statement="INSERT INTO components(id,source_sha256,body_index,byte_size,revision,metadata_json,evidence_json,native_relpath,native_sha256,source_path,category,standard,thread_diameter_mm,thread_pitch_mm,length_mm,material,manufacturer,part_number,name,description,aliases,geometry_verified) VALUES(?,?,?,0,1,?,'{}','','','synthetic-benchmark','fastener.screw','ISO4762',?,1,?,'steel','benchmark',?,'Socket screw','Synthetic metadata benchmark only','parafuso screw bolt',0)";check(sqlite3_prepare_v2(db,statement,-1,&insert,nullptr)==SQLITE_OK,"prepare catalogue seed");auto began=std::chrono::steady_clock::now();
    for(int i=0;i<100000;++i){std::ostringstream number;number<<std::setw(6)<<std::setfill('0')<<i;auto id="benchmark:"+number.str(),hash=std::string(58,'0')+number.str(),part="SC-"+number.str(),normalizedPart="sc-"+number.str();V metadata=V::makeObj();metadata.set("name",V::makeStr("Synthetic socket screw "+part));metadata.set("category",V::makeStr("fastener.screw"));metadata.set("standard",V::makeStr("ISO 4762"));metadata.set("part_number",V::makeStr(part));metadata.set("thread_diameter_mm",V::makeNum(4+(i%8)));metadata.set("length_mm",V::makeNum(10+(i%20)*5));auto meta=metadata.dump();sqlite3_reset(insert);sqlite3_clear_bindings(insert);sqlite3_bind_text(insert,1,id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(insert,2,hash.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int(insert,3,0);sqlite3_bind_text(insert,4,meta.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_double(insert,5,4+(i%8));sqlite3_bind_double(insert,6,10+(i%20)*5);sqlite3_bind_text(insert,7,normalizedPart.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(insert)!=SQLITE_DONE){sqlite3_finalize(insert);throw std::runtime_error("seed catalogue failed");}}
    sqlite3_finalize(insert);sql(db,"COMMIT;ANALYZE;");double seedMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-began).count();check(library.info().find("components")->num==100000,"benchmark uses 100k synthetic indexed metadata records");
    auto measure=[&](const char* kind,const V& query){std::vector<double> times;for(int i=0;i<40;++i){auto start=std::chrono::steady_clock::now();auto result=library.search(query);auto end=std::chrono::steady_clock::now();check(!result.find("components")->arr.empty(),"representative benchmark query returns records");if(i>=5)times.push_back(std::chrono::duration<double,std::milli>(end-start).count());}V row=V::makeObj();row.set("query",V::makeStr(kind));row.set("scope",V::makeStr("ComponentLibrary search including prepare/bind/SQLite/materialized metadata JSON; excludes network, tool dispatch and native import"));row.set("samples",V::makeNum(times.size()));row.set("p50_ms",V::makeNum(percentile(times,.50)));row.set("p95_ms",V::makeNum(percentile(times,.95)));return row;};
    V rows=V::makeArr();rows.arr.push_back(measure("exact declared ISO/thread/pitch/length",json(R"({"category":"screw","standard":"ISO4762","thread_diameter_mm":6,"thread_pitch_mm":1,"length_mm":20,"limit":20})")));rows.arr.push_back(measure("broad Portuguese FTS common word",json(R"({"text":"parafuso","limit":20})")));rows.arr.push_back(measure("FTS plus exact part number and dimensions",json(R"({"text":"parafuso","part_number":"SC-000042","thread_diameter_mm":6,"length_mm":20,"limit":20})")));
    sqlite3_stmt* plan=nullptr;check(sqlite3_prepare_v2(db,"EXPLAIN QUERY PLAN SELECT id FROM components WHERE category='fastener.screw' AND standard='ISO4762' AND thread_diameter_mm=6 AND thread_pitch_mm=1 AND length_mm=20",-1,&plan,nullptr)==SQLITE_OK,"prepare index-plan evidence");std::string planText;while(sqlite3_step(plan)==SQLITE_ROW){auto text=sqlite3_column_text(plan,3);if(text)planText+=(const char*)text;}sqlite3_finalize(plan);check(planText.find("components_dimensions")!=std::string::npos,"exact lookup actually uses composite index");
    V receipt=V::makeObj();receipt.set("format",V::makeStr("ark-component-library-benchmark-v1"));receipt.set("records",V::makeNum(100000));receipt.set("fixture",V::makeStr("synthetic declared catalogue metadata; no certified/native geometry in benchmark records"));receipt.set("sqlite_version",V::makeStr(sqlite3_libversion()));receipt.set("seed_ms",V::makeNum(seedMs));receipt.set("measurements",rows);receipt.set("exact_query_plan",V::makeStr(planText));receipt.set("superiority_claim",V::makeBool(false));std::cout<<receipt.dump()<<'\n';if(!outputPath.empty())write(fs::u8path(outputPath),receipt.dump());
}
int main(int argc,char** argv){try{ingestionAndSearch();multiAgentTransactions();downloadEvidenceContracts();std::string output;if(argc==3&&std::string(argv[1])=="--benchmark-output")output=argv[2];catalogBenchmark(output);std::cout<<"Component library checks passed: "<<checks<<'\n';return 0;}catch(const std::exception& error){std::cerr<<"Component library checks failed: "<<error.what()<<'\n';return 1;}}
